class SimActor:
    def __init__(s, name): s.name = name; s.fr = REC[name]; s.segs = []
    def _snap(s, ta):
        f = max(0.0, min(len(s.fr) - 1.001, ta/sim.REC)); i = int(f); w = f - i
        a, b = s.fr[i], s.fr[i + 1]
        return a[0]*(1 - w) + b[0]*w, (a[1] if w < 0.5 else b[1]), a[2]
    def joints(s, ta):
        S_, face, _ = s._snap(ta); J = np.zeros((18, 2)); j = sim.JI
        hip, nk, hd = S_[j['hip']], S_[j['neck']], S_[j['head']]
        J[IDX['hip']] = hip; J[IDX['neck']] = nk; J[IDX['chest']] = hip + (nk - hip)*0.8; J[IDX['head']] = hd
        sh = nk + (hip - nk)*0.08
        for side, src in (('r', 'r'), ('l', 'f')):
            J[IDX[side + 'sh']] = sh; J[IDX[side + 'el']] = S_[j[src + 'el']]; J[IDX[side + 'hand']] = S_[j[src + 'hand']]
            J[IDX[side + 'hp']] = hip; J[IDX[side + 'kn']] = S_[j[src + 'kn']]; ft = S_[j[src + 'ft']]
            J[IDX[side + 'ft']] = ft; d = ft - J[IDX[side + 'kn']]; L = np.hypot(*d) or 1
            J[IDX[side + 'toe']] = ft + np.array([-d[1], d[0]])/L*9*(-face if d[1] > 0 else face) if False else ft + np.array([face*9.0, 1.0])
        Z = np.zeros(18); Z[[IDX[n] for n in NAMES if n.startswith('l')]] = 1.0; Z[[IDX[n] for n in NAMES if n.startswith('r')]] = -1.0
        return J, Z
    def sword_at(s, ta): return s._snap(ta)[2]
    def down_at(s, ta):
        return any(k == 'ko' and d['victim'] == s.name and t <= ta < t + 1.0 for t, k, d in EVENTS)
